select

from survey_assign_org_extension
where 1=1

   and survey_id = #{surveyId,jdbcType=BIGINT}


    and survey_info_id = #{surveyInfoId,jdbcType=BIGINT}


    and survey_assign_org_id = #{surveyAssignOrgId,jdbcType=BIGINT}


    and extension_state = #{extensionState,jdbcType=INTEGER}




      order by id asc



  order by id desc
